pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 blockNumber) public {
        vm.assume(amount <= 10 ether);
        vm.assume(blockNumber > 0);
        vm.roll(blockNumber);
        vm.warp(1);

        address sender = makeAddr("sender");
        vm.deal(sender, amount);

        uint256 balanceBefore = address(c).balance;
        bool success;
        vm.prank(sender);
        try c.fallback{value: amount}() {
            success = true;
        } catch {
            success = false;
        }
        uint256 balanceAfter = address(c).balance;

        if (success) {
            if (amount == 0) {
                assertTrue(balanceAfter == balanceBefore);
            } else {
                assertTrue(balanceAfter <= balanceBefore - 10 ether);
            }
        }
    }
}

