import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 msgValue, uint256 blockTimestamp, uint256 blockNumber) public {
        // Keep msgValue admissible: 0 to 10 ether (the tested value range)
        vm.assume(msgValue <= 10 ether);
        // Warp to a future timestamp; no constraint on it relative to pastBlockTime
        vm.warp(blockTimestamp);
        // Set block number; modulo 15 decides transfer
        vm.roll(blockNumber);

        // Drive c through its public fallback with fuzzed inputs
        vm.deal(address(this), msgValue);
        (bool ok, ) = address(c).call{value: msgValue}("");

