pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value) public {
        // Restrict to payable amounts that fit in 256 bits and are not 10 ether
        vm.assume(value != 10 ether);
        // Bound to a reasonable range to avoid fuzzer overflow issues, but keep it wide
        value = bound(value, 0, 1000 ether);
        vm.assume(value != 10 ether);

        // Warp to a future timestamp so that block.timestamp > pastBlockTime (which is 0 initially)
        vm.warp(1);

        // Record state before the call
        uint256 pastBefore = c.pastBlockTime();

        // Fund an arbitrary caller and attempt the fallback call with an invalid value
        address caller = address(0x1234);
        vm.deal(caller, value);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: value}("");

        // Regardless of whether the call reverted or not, the timestamp should NOT have changed
        // because the msg.value is not 10 ether, so the require should have failed.
        // But the buggy version advances it for 1 ether. We assert that pastBlockTime stayed untouched.
        assertEq(c.pastBlockTime(), pastBefore, "pastBlockTime changed for disallowed value");
    }
}

