        vm.assume(nextTimestamp >= 1000);

        // Warp to the fuzzed timestamp and provide Ether
        vm.warp(nextTimestamp);
        vm.roll(2);
        vm.deal(address(this), 10 ether);

        uint256 before = c.pastBlockTime();
        (bool okSecond, ) = address(c).call{value: 10 ether}("");
        require(okSecond, "second call failed");
        uint256 afterVal = c.pastBlockTime();

        assertTrue(afterVal > before);
    }
}

