pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum1, uint256 blockNum2) public {
        // Ensure block numbers are different enough to avoid collision, but keep domain wide
        vm.assume(blockNum1 != blockNum2);
        // Ensure block numbers are not equal to 0 for division safety, and within realistic range
        bound(blockNum1, 1, type(uint128).max);
        bound(blockNum2, 1, type(uint128).max);

        // Ensure we have fresh contract instance with no initial pastBlockTime
        // Use two different actors
        address actor1 = address(0x1000);
        address actor2 = address(0x2000);

        // Fund actors
        vm.deal(actor1, 100 ether);
        vm.deal(actor2, 100 ether);

        // First call at block number blockNum1, timestamp 100
        vm.roll(blockNum1);
        vm.warp(100);
        vm.prank(actor1);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");

        // Second call at block number blockNum2, same timestamp 100
        vm.roll(blockNum2);
        vm.warp(100);
        vm.prank(actor2);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // Reference contract: strict timestamp check means ok2 == false (revert)
        // Buggy contract: ok2 == true (pastBlockTime set to block.timestamp + 1, so next same-timestamp call passes)
        assertTrue(!ok2);
    }
}

