pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp, uint256 salt) public {
        // Keep timestamp in a reasonable range and non-zero
        timestamp = bound(timestamp, 1, 1000000);
        // Use salt to decide whether to make two calls at the same timestamp
        uint256 targetBlock = bound(salt, 1, 100000) + 1;

        // Warp to the chosen timestamp and set block number to targetBlock
        vm.warp(timestamp);
        vm.roll(targetBlock);

        // Fund an EOA and make first fallback call with exact 10 ether
        address caller = makeAddr("caller");
        vm.deal(caller, 20 ether);
        vm.prank(caller);
        (bool success1, ) = address(c).call{value: 10 ether}("");
        require(success1, "first call must succeed");

        // pastBlockTime is now timestamp (reference) or timestamp+1 (buggy)
        // Try a second call within the same block timestamp.
        // Reference must revert (timestamp == pastBlockTime). Buggy may succeed.
        uint256 snapshotId = vm.snapshot();
        vm.prank(caller);
        (bool success2, ) = address(c).call{value: 10 ether}("");

        // Restore state before second call and re-run via try/catch to capture revert flag
        vm.revertTo(snapshotId);
        bool ok;
        vm.prank(caller);
        try c.fallback{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: reference C always reverts on a second call at same timestamp,
        // because pastBlockTime == timestamp after first call (strict > required).
        // Buggy C with +1 allows the second call, so ok becomes true.
        // We assert that the call must revert: reference passes, bug fails.
        assertTrue(!ok, "second call must revert");
    }
}

