pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint256 ts, uint256 deltaBlocks) public {
        uint256 actorPriv = 0x1234;
        address actor = vm.addr(actorPriv);
        vm.deal(actor, 30 ether);

        vm.warp(ts);
        vm.roll(blockNum);

        // First call: must succeed on both versions
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first call must succeed");

        // Advance blocks but not timestamp
        // The fuzzer controls deltaBlocks; we restrict to >= 1 so that the second call
        // happens in a strictly greater block number but same timestamp.
        deltaBlocks = bound(deltaBlocks, 1, 100000);
        vm.roll(blockNum + deltaBlocks);
        // timestamp unchanged

        // Second call with same timestamp
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // Balance after second call
        uint256 bal = address(c).balance;

        // Property: if the second call did not revert (ok2 == true),
        // then the contract balance must be 20 ether.
        // In the reference version ok2 is always false when timestamp doesn't advance,
        // so the implication holds vacuously.
        // In the buggy version the fuzzer can make ok2 true and bal != 20 ether
        // (because the transfer inside the fallback may have emptied the contract, depending on blockNum).
        assertTrue(!ok2 || bal == 20 ether);
    }
}

